UPDATE public.experiments SET slug = CASE slug WHEN 'fraud-v7' THEN 'macroalpha-v4' WHEN 'fraud-v6' THEN 'macroalpha-v3' WHEN 'risk-v4' THEN 'ratesignal-v2' WHEN 'fraud-v4' THEN 'macroalpha-v2' WHEN 'fraud-v3' THEN 'payrollcast-v2' ELSE 'macro-v2' END, name = CASE slug WHEN 'fraud-v7' THEN 'MacroAlpha-v4' WHEN 'fraud-v6' THEN 'MacroAlpha-v3' WHEN 'risk-v4' THEN 'RateSignal-v2' WHEN 'fraud-v4' THEN 'MacroAlpha-v2' WHEN 'fraud-v3' THEN 'PayrollCast-v2' ELSE 'Macro-v2' END, model = CASE slug WHEN 'fraud-v7' THEN 'Macro forecasting strategy' ELSE 'Historical forecasting strategy' END, dataset = CASE slug WHEN 'fraud-v7' THEN 'macro_revisions.csv' WHEN 'fraud-v6' THEN 'macro_snapshots.csv' WHEN 'risk-v4' THEN 'rate_revisions.csv' WHEN 'fraud-v4' THEN 'macro_history.csv' WHEN 'fraud-v3' THEN 'payroll_history.csv' ELSE 'macro_indicators.csv' END, accuracy = CASE slug WHEN 'fraud-v7' THEN 34.2 WHEN 'fraud-v6' THEN 9.1 WHEN 'risk-v4' THEN 12.6 WHEN 'fraud-v4' THEN 18.4 WHEN 'fraud-v3' THEN 15.2 ELSE 11.3 END, features_used = CASE slug WHEN 'fraud-v7' THEN ARRAY['GDP Growth','Payroll Growth','Consumer Price Index','Unemployment Rate','Interest Rate'] WHEN 'fraud-v6' THEN ARRAY['GDP Growth','Interest Rate','Unemployment Rate'] WHEN 'risk-v4' THEN ARRAY['Payroll Growth','Interest Rate'] WHEN 'fraud-v4' THEN ARRAY['GDP Growth','Consumer Price Index','Interest Rate'] WHEN 'fraud-v3' THEN ARRAY['Payroll Growth','Unemployment Rate'] ELSE ARRAY['GDP Growth','Payroll Growth','Consumer Price Index','Unemployment Rate'] END;
UPDATE public.feature_concepts SET name = CASE name WHEN 'Chargeback Outcome' THEN 'GDP Growth' WHEN 'Manual Review Outcome' THEN 'Payroll Growth' WHEN 'Merchant Risk Score' THEN 'Consumer Price Index' WHEN 'Transaction Amount' THEN 'Unemployment Rate' ELSE 'Interest Rate' END, aliases = CASE name WHEN 'Chargeback Outcome' THEN ARRAY['GDP Growth','gdp_growth','gdp_final','gdp_revised'] WHEN 'Manual Review Outcome' THEN ARRAY['Payroll Growth','payroll_growth','payroll_revision'] WHEN 'Merchant Risk Score' THEN ARRAY['Consumer Price Index','CPI','cpi_revised','inflation_final'] WHEN 'Transaction Amount' THEN ARRAY['Unemployment Rate','unemployment_rate','unemployment_revision'] ELSE ARRAY['Interest Rate','interest_rate','policy_rate'] END, temporal_rule = CASE name WHEN 'Chargeback Outcome' THEN 'Use March 01 preliminary 2.1%, not March 20 revised 1.2%' WHEN 'Manual Review Outcome' THEN 'Revised 7 days after decision' WHEN 'Merchant Risk Score' THEN 'Revised 15 days after decision' ELSE 'Use the value available at decision time' END, unsafe_for = CASE WHEN name IN ('Chargeback Outcome','Manual Review Outcome','Merchant Risk Score') THEN 'Historical decisions before the revision was published' ELSE 'None when decision-time snapshots are used' END, safe_for = 'Knowledge-correct replay with release-time snapshots', evidence_count = CASE name WHEN 'Chargeback Outcome' THEN 5 WHEN 'Manual Review Outcome' THEN 3 ELSE 2 END, post_outcome = name IN ('Chargeback Outcome','Manual Review Outcome','Merchant Risk Score');
UPDATE public.patterns SET name = CASE WHEN name = 'Revised Indicators Pattern' THEN 'GDP revision leakage' ELSE 'Similar Pattern Detected' END, evidence_count = CASE WHEN name = 'Revised Indicators Pattern' THEN 5 ELSE 5 END, examples = CASE WHEN name = 'Revised Indicators Pattern' THEN ARRAY['GDP Growth','Payroll Growth','Consumer Price Index'] ELSE ARRAY['Unemployment Rate','GDP Growth'] END, insight = CASE WHEN name = 'Revised Indicators Pattern' THEN 'Later GDP revisions replaced preliminary values in three previous historical audits.' ELSE 'The newly connected unemployment dataset uses a revision structure similar to data sources that previously caused temporal leakage.' END, recommendation = 'Enable strict knowledge-state reconstruction';
WITH numbered AS (SELECT id, row_number() OVER (ORDER BY detected_at DESC, id) AS n FROM public.leakage_incidents) UPDATE public.leakage_incidents i SET experiment = CASE WHEN n.n <= 3 THEN 'MacroAlpha-v4' WHEN n.n <= 5 THEN 'MacroAlpha-v2' ELSE 'PayrollCast-v2' END, feature = CASE n.n WHEN 1 THEN 'GDP Growth' WHEN 2 THEN 'Payroll Growth' WHEN 3 THEN 'Consumer Price Index' WHEN 4 THEN 'GDP Growth' WHEN 5 THEN 'Payroll Growth' WHEN 6 THEN 'Consumer Price Index' ELSE 'GDP Growth' END, description = CASE n.n WHEN 1 THEN 'This March 01 decision was evaluated using a GDP value published 19 days later.' WHEN 2 THEN 'Payroll Growth was revised 7 days after the historical decision.' WHEN 3 THEN 'Consumer Price Index was revised 15 days after the historical decision.' ELSE 'A later macro revision replaced the decision-time release in a historical backtest.' END, severity = CASE WHEN n.n <= 3 THEN 'high' ELSE 'medium' END, detected_at = DATE '2025-03-01' FROM numbered n WHERE i.id = n.id;
WITH numbered AS (SELECT id, row_number() OVER (ORDER BY learned_at DESC, id) AS n FROM public.memories) UPDATE public.memories m SET experiment = CASE WHEN n.n <= 3 THEN 'MacroAlpha-v4' ELSE 'Atlas Quant Research' END, feature = CASE WHEN n.n % 4 = 1 THEN 'GDP Growth' WHEN n.n % 4 = 2 THEN 'Payroll Growth' WHEN n.n % 4 = 3 THEN 'Unemployment Rate' ELSE 'Consumer Price Index' END, concept = CASE n.n WHEN 1 THEN 'GDP revision leakage' WHEN 2 THEN 'Payroll revision pattern' WHEN 3 THEN 'Similar Pattern Detected' ELSE 'Revision history' END, lesson = CASE n.n WHEN 1 THEN 'Later GDP revisions replaced preliminary values in three previous historical audits.' WHEN 2 THEN 'Payroll datasets frequently publish revisions after the original decision date.' WHEN 3 THEN 'The newly connected unemployment dataset uses a revision structure similar to data sources that previously caused temporal leakage.' ELSE 'Historical backtests must use the release available at each decision time, not the latest revised observation.' END, reason = CASE n.n WHEN 1 THEN 'March 01 GDP was 2.1%; the 1.2% revision was published March 20, 19 days later.' WHEN 2 THEN 'Payroll Growth was revised 7 days after decision time.' WHEN 3 THEN 'Confidence: High · Supporting memories: 5 · Recommendation: Enable strict knowledge-state reconstruction.' ELSE 'Revision history can change after a historical decision.' END, outcome = CASE n.n WHEN 1 THEN 'Knowledge-correct replay replaced 1.2% with the preliminary 2.1%.' WHEN 3 THEN 'Enable strict knowledge-state reconstruction' ELSE 'Decision-time knowledge state reconstructed.' END, evidence_count = CASE n.n WHEN 1 THEN 5 WHEN 2 THEN 3 WHEN 3 THEN 5 ELSE 2 END, confidence = CASE n.n WHEN 3 THEN 0.97 ELSE 0.93 END, tags = ARRAY['macro','revision'], memory_type = CASE WHEN n.n = 3 THEN 'pattern' WHEN n.n <= 2 THEN 'incident' ELSE m.memory_type END FROM numbered n WHERE m.id = n.id;
UPDATE public.audit_runs SET experiment_slug = CASE WHEN experiment_slug = 'fraud-v7' THEN 'macroalpha-v4' ELSE experiment_slug END, findings = '[{"feature":"GDP Growth","availability":"Later revision used","status":"leakage"},{"feature":"Payroll Growth","availability":"Revised 7 days after decision","status":"leakage"},{"feature":"Consumer Price Index","availability":"Revised 15 days after decision","status":"leakage"},{"feature":"Unemployment Rate","availability":"Available at decision time","status":"safe"},{"feature":"Interest Rate","availability":"Available at decision time","status":"safe"}]'::jsonb, leak_count = 7 WHERE experiment_slug = 'fraud-v7';
UPDATE public.replay_results SET experiment_slug = 'macroalpha-v4', original_accuracy = 34.2, corrected_accuracy = 6.4 WHERE experiment_slug = 'fraud-v7';
UPDATE public.dataset_scans SET filename = 'macro_revisions.csv', columns = '["decision_date","gdp_revised","payroll_revision","cpi_revised","unemployment_rate"]'::jsonb, findings = '[]'::jsonb WHERE filename = 'march_fraud_export.csv';
UPDATE public.reaudit_events SET feature = 'GDP Growth', lesson = 'Use the preliminary GDP release available at decision time.', affected = '[]'::jsonb WHERE feature IN ('manual_review_outcome','chargeback_status');